#include <stdio.h>

#define MAXN 100000

static int X[MAXN];
static int Y[MAXN];

int main(void) {
    int A, B;

    if (scanf("%d %d", &A, &B) != 2) return 0;

    for (int i = 0; i < A; i++) {
        scanf("%d", &X[i]);
    }
    for (int i = 0; i < B; i++) {
        scanf("%d", &Y[i]);
    }

    int j = 0;
    for (int i = 0; i < A && j < B; i++) {
        if (X[i] == Y[j]) {
            j++;
        }
    }

    if (j == B) {
        putchar('S');
    } else {
        putchar('N');
    }
    putchar('\n');

    return 0;
}
